class TestRawTelemetrySchema:
    """Validate schema contract enforcement."""

    def test_valid_data_passes_schema(self, valid_raw_telemetry):
        """Valid telemetry must pass schema validation."""
        validated = RawTelemetrySchema.validate(valid_raw_telemetry)
        assert len(validated) == len(valid_raw_telemetry)

    def test_invalid_node_id_format(self, valid_raw_telemetry):
        """Node IDs must match ^node-\\d+$ pattern."""
        df = valid_raw_telemetry.copy()
        df.loc[0, "node_id"] = "invalid-node"
        with pytest.raises(pa.errors.SchemaError):
            RawTelemetrySchema.validate(df)

    def test_cpu_util_out_of_bounds(self, valid_raw_telemetry):
        """CPU utilization must be within [0, 100]."""
        df = valid_raw_telemetry.copy()
        df.loc[0, "cpu_util"] = 150.0
        with pytest.raises(pa.errors.SchemaError):
            RawTelemetrySchema.validate(df)

    def test_mem_util_negative(self, valid_raw_telemetry):
        """Memory utilization cannot be negative."""
        df = valid_raw_telemetry.copy()
        df.loc[0, "mem_util"] = -5.0
        with pytest.raises(pa.errors.SchemaError):
            RawTelemetrySchema.validate(df)

    def test_nullable_fields_accept_nan(self, valid_raw_telemetry):
        """CPU/MEM fields are nullable and should accept NaN."""
        df = valid_raw_telemetry.copy()
        df.loc[0, "cpu_util"] = np.nan
        df.loc[1, "mem_util"] = np.nan
        validated = RawTelemetrySchema.validate(df)
        assert validated.loc[0, "cpu_util"] is np.nan or pd.isna(validated.loc[0, "cpu_util"])

    def test_missing_required_column(self, valid_raw_telemetry):
        """Missing required column must raise SchemaError."""
        df = valid_raw_telemetry.drop(columns=["net_throughput"])
        with pytest.raises(pa.errors.SchemaError):
            RawTelemetrySchema.validate(df)


