class TestTemporalAlignment:
    """Validate resampling to fixed cadence."""

    def test_initialization(self, pipeline_config):
        """Component must initialize with valid config."""
        aligner = TemporalAlignment(freq=pipeline_config["resample_freq"])
        assert aligner.freq == "30s"

    def test_resample_irregular_data(self, irregular_telemetry, pipeline_config):
        """Irregular data must be resampled to fixed 30s intervals."""
        aligner = TemporalAlignment(freq=pipeline_config["resample_freq"])
        result = aligner.transform(irregular_telemetry)
        
        # Verify fixed frequency
        for node in result["node_id"].unique():
            node_data = result[result["node_id"] == node]
            diffs = node_data["timestamp"].diff().dropna()
            assert (diffs == pd.Timedelta(seconds=30)).all()

    def test_no_data_loss_on_regular_input(self, valid_raw_telemetry, pipeline_config):
        """Regular input should not lose rows."""
        aligner = TemporalAlignment(freq=pipeline_config["resample_freq"])
        result = aligner.transform(valid_raw_telemetry)
        assert len(result) == len(valid_raw_telemetry)

    def test_multi_node_preservation(self, irregular_telemetry, pipeline_config):
        """All node IDs must be preserved after alignment."""
        aligner = TemporalAlignment(freq=pipeline_config["resample_freq"])
        result = aligner.transform(irregular_telemetry)
        assert set(result["node_id"].unique()) == {"node-1", "node-2", "node-3"}

    def test_timestamp_monotonicity(self, irregular_telemetry, pipeline_config):
        """Timestamps must be strictly increasing per node."""
        aligner = TemporalAlignment(freq=pipeline_config["resample_freq"])
        result = aligner.transform(irregular_telemetry)
        for node in result["node_id"].unique():
            node_ts = result[result["node_id"] == node]["timestamp"]
            assert node_ts.is_monotonic_increasing

    @pytest.mark.parametrize("invalid_freq", ["invalid", "", "10x"])
    def test_invalid_frequency(self, invalid_freq):
        """Invalid frequency strings must raise ValueError."""
        with pytest.raises(ValueError):
            TemporalAlignment(freq=invalid_freq)


