class TestClockSkewCorrector:
    """Validate clock drift detection and correction."""

    def test_detect_skew(self, skewed_telemetry, pipeline_config):
        """Known drift must be detected within tolerance."""
        corrector = ClockSkewCorrector(max_skew_seconds=pipeline_config["max_skew_seconds"])
        skews = corrector.detect_skew(skewed_telemetry)
        
        # node-2 has +2.5s drift, node-3 has -1.5s drift
        assert abs(skews.get("node-2", 0) - 2.5) < 0.5
        assert abs(skews.get("node-3", 0) - (-1.5)) < 0.5

    def test_correct_skew(self, skewed_telemetry, pipeline_config):
        """Correction must align timestamps to reference."""
        corrector = ClockSkewCorrector(max_skew_seconds=pipeline_config["max_skew_seconds"])
        corrected = corrector.transform(skewed_telemetry)
        
        # After correction, all nodes should have aligned timestamps
        for node in corrected["node_id"].unique():
            node_ts = corrected[corrected["node_id"] == node]["timestamp"]
            assert node_ts.is_monotonic_increasing

    def test_no_skew_no_change(self, valid_raw_telemetry, pipeline_config):
        """Data without skew should remain unchanged."""
        corrector = ClockSkewCorrector(max_skew_seconds=pipeline_config["max_skew_seconds"])
        result = corrector.transform(valid_raw_telemetry)
        pd.testing.assert_frame_equal(result, valid_raw_telemetry)

    def test_excessive_skew_flagged(self, pipeline_config):
        """Skew beyond max threshold must be flagged or rejected."""
        df = valid_raw_telemetry()
        # Inject 10s drift (exceeds 5s max)
        mask = df["node_id"] == "node-1"
        df.loc[mask, "timestamp"] = df.loc[mask, "timestamp"] + pd.Timedelta(seconds=10)
        
        corrector = ClockSkewCorrector(max_skew_seconds=pipeline_config["max_skew_seconds"])
        with pytest.raises(ValueError, match="skew"):
            corrector.transform(df)


