class TestRollingAggregator:
    """Validate windowed statistics computation."""

    def test_rolling_mean(self, valid_raw_telemetry, pipeline_config):
        """Rolling mean must be computed correctly."""
        aggregator = RollingAggregator(
            window_size=pipeline_config["window_size"],
            min_periods=pipeline_config["min_periods"]
        )
        result = aggregator.transform(valid_raw_telemetry)
        
        # Verify rolling mean for first node
        node1 = result[result["node_id"] == "node-1"].reset_index(drop=True)
        expected_mean = valid_raw_telemetry[valid_raw_telemetry["node_id"] == "node-1"]["cpu_util"].rolling(
            window=5, min_periods=3
        ).mean()
        
        np.testing.assert_allclose(
            node1["cpu_util_rolling_mean"].dropna().values,
            expected_mean.dropna().values,
            rtol=1e-6
        )

    def test_min_periods_enforcement(self, valid_raw_telemetry, pipeline_config):
        """Values below min_periods must be NaN."""
        aggregator = RollingAggregator(window_size=5, min_periods=5)
        result = aggregator.transform(valid_raw_telemetry)
        
        node1 = result[result["node_id"] == "node-1"]["cpu_util_rolling_mean"]
        # First 4 values should be NaN (window=5, min_periods=5)
        assert node1.iloc[:4].isna().all()
        assert not node1.iloc[4:].isna().any()

    def test_multiple_metrics(self, valid_raw_telemetry, pipeline_config):
        """All numeric columns must have rolling statistics."""
        aggregator = RollingAggregator(
            window_size=pipeline_config["window_size"],
            min_periods=pipeline_config["min_periods"]
        )
        result = aggregator.transform(valid_raw_telemetry)
        
        expected_cols = [
            "cpu_util_rolling_mean", "mem_util_rolling_mean", "net_throughput_rolling_mean",
            "cpu_util_rolling_std", "mem_util_rolling_std", "net_throughput_rolling_std",
        ]
        for col in expected_cols:
            assert col in result.columns

    def test_rolling_std_correctness(self, valid_raw_telemetry, pipeline_config):
        """Rolling standard deviation must match pandas computation."""
        aggregator = RollingAggregator(
            window_size=pipeline_config["window_size"],
            min_periods=pipeline_config["min_periods"]
        )
        result = aggregator.transform(valid_raw_telemetry)
        
        node1 = result[result["node_id"] == "node-1"].reset_index(drop=True)
        expected_std = valid_raw_telemetry[valid_raw_telemetry["node_id"] == "node-1"]["cpu_util"].rolling(
            window=5, min_periods=3
        ).std()
        
        np.testing.assert_allclose(
            node1["cpu_util_rolling_std"].dropna().values,
            expected_std.dropna().values,
            rtol=1e-6
        )

    def test_empty_dataframe(self, pipeline_config):
        """Empty input must return empty output without error."""
        aggregator = RollingAggregator(
            window_size=pipeline_config["window_size"],
            min_periods=pipeline_config["min_periods"]
        )
        empty_df = pd.DataFrame(columns=["node_id", "timestamp", "cpu_util", "mem_util", "net_throughput"])
        result = aggregator.transform(empty_df)
        assert result.empty


