from hypothesis import given, settings, strategies as st

class TestPropertyBased:
    """Property-based validation of pipeline invariants."""

    @settings(max_examples=50)
    @given(
        st.integers(min_value=1, max_value=10),
        st.integers(min_value=1, max_value=100),
    )
    def test_pipeline_preserves_node_count(self, num_nodes, num_timestamps):
        """Pipeline must preserve the number of unique nodes."""
        timestamps = pd.date_range("2026-08-01", periods=num_timestamps, freq="1s")
        rows = []
        for node_idx in range(num_nodes):
            node_id = f"node-{node_idx + 1}"
            for ts in timestamps:
                rows.append({
                    "node_id": node_id,
                    "timestamp": ts,
                    "cpu_util": np.random.uniform(0, 100),
                    "mem_util": np.random.uniform(0, 100),
                    "net_throughput": np.random.uniform(0, 1000),
                })
        df = pd.DataFrame(rows)
        
        pipeline = FeaturePipeline(
            resample_freq="1s",
            max_skew_seconds=2.0,
            impute_method="ffill",
            interpolation_limit=2,
            window_size=3,
            min_periods=2,
        )
        result = pipeline.fit_transform(df)
        
        assert len(result["node_id"].unique()) == num_nodes

    @settings(max_examples=50)
    @given(
        st.floats(min_value=0.0, max_value=100.0),
        st.floats(min_value=0.0, max_value=100.0),
    )
    def test_imputation_bounds(self, cpu_val, mem_val):
        """Imputed values must remain within physical bounds."""
        df = pd.DataFrame({
            "node_id": ["node-1"] * 10,
            "timestamp": pd.date_range("2026-08-01", periods=10, freq="1s"),
            "cpu_util": [cpu_val] + [np.nan] * 9,
            "mem_util": [mem_val] + [np.nan] * 9,
            "net_throughput": [100.0] * 10,
        })
        
        imputer = MissingDataImputer(method="ffill", interpolation_limit=5)
        result = imputer.transform(df)
        
        assert result["cpu_util"].between(0, 100).all()
        assert result["mem_util"].between(0, 100).all()


