class TestPerformance:
    """Validate pipeline performance characteristics."""

    def test_pipeline_throughput(self, pipeline_config):
        """Pipeline must process 10k rows in under 5 seconds."""
        import time
        
        # Generate 10k rows
        timestamps = pd.date_range("2026-08-01", periods=2000, freq="1s")
        rows = []
        for node in ["node-1", "node-2", "node-3", "node-4", "node-5"]:
            for ts in timestamps:
                rows.append({
                    "node_id": node,
                    "timestamp": ts,
                    "cpu_util": np.random.uniform(0, 100),
                    "mem_util": np.random.uniform(0, 100),
                    "net_throughput": np.random.uniform(0, 1000),
                })
        df = pd.DataFrame(rows)
        
        pipeline = FeaturePipeline(
            resample_freq=pipeline_config["resample_freq"],
            max_skew_seconds=pipeline_config["max_skew_seconds"],
            impute_method=pipeline_config["impute_method"],
            interpolation_limit=pipeline_config["interpolation_limit"],
            window_size=pipeline_config["window_size"],
            min_periods=pipeline_config["min_periods"],
        )
        
        start = time.perf_counter()
        pipeline.fit_transform(df)
        elapsed = time.perf_counter() - start
        
        assert elapsed < 5.0, f"Pipeline took {elapsed:.2f}s, expected < 5s"

    def test_memory_efficiency(self, pipeline_config):
        """Pipeline must not cause excessive memory growth."""
        import tracemalloc
        
        # Generate moderate dataset
        timestamps = pd.date_range("2026-08-01", periods=500, freq="1s")
        rows = []
        for node in ["node-1", "node-2", "node-3"]:
            for ts in timestamps:
                rows.append({
                    "node_id": node,
                    "timestamp": ts,
                    "cpu_util": np.random.uniform(0, 100),
                    "mem_util": np.random.uniform(0, 100),
                    "net_throughput": np.random.uniform(0, 1000),
                })
        df = pd.DataFrame(rows)
        
        pipeline = FeaturePipeline(
            resample_freq=pipeline_config["resample_freq"],
            max_skew_seconds=pipeline_config["max_skew_seconds"],
            impute_method=pipeline_config["impute_method"],
            interpolation_limit=pipeline_config["interpolation_limit"],
            window_size=pipeline_config["window_size"],
            min_periods=pipeline_config["min_periods"],
        )
        
        tracemalloc.start()
        pipeline.fit_transform(df)
        current, peak = tracemalloc.get_traced_memory()
        tracemalloc.stop()
        
        # Peak memory should be under 500MB
        assert peak < 500 * 1024 * 1024, f"Peak memory {peak/1e6:.1f}MB exceeds 500MB limit"


