    def test_empty_input(self, pipeline_config):
        """Empty DataFrame must not crash pipeline."""
        empty_df = pd.DataFrame(columns=["node_id", "timestamp", "cpu_util", "mem_util", "net_throughput"])
        
        pipeline = FeaturePipeline(
            resample_freq=pipeline_config["resample_freq"],
            max_skew_seconds=pipeline_config["max_skew_seconds"],
            impute_method=pipeline_config["impute_method"],
            interpolation_limit=pipeline_config["interpolation_limit"],
            window_size=pipeline_config["window_size"],
            min_periods=pipeline_config["min_periods"],
        )
        
        result = pipeline.fit_transform(empty_df)
        assert result.empty

    def test_single_row_input(self, pipeline_config):
        """Single row must be handled gracefully."""
        df = pd.DataFrame({
            "node_id": ["node-1"],
            "timestamp": [pd.Timestamp("2026-08-01T00:00:00")],
            "cpu_util": [50.0],
            "mem_util": [50.0],
            "net_throughput": [100.0],
        })
        
        pipeline = FeaturePipeline(
            resample_freq=pipeline_config["resample_freq"],
            max_skew_seconds=pipeline_config["max_skew_seconds"],
            impute_method=pipeline_config["impute_method"],
            interpolation_limit=pipeline_config["interpolation_limit"],
            window_size=pipeline_config["window_size"],
            min_periods=pipeline_config["min_periods"],
        )
        
        result = pipeline.fit_transform(df)
        assert not result.empty

    def test_all_nan_values(self, pipeline_config):
        """All NaN values must be imputed without error."""
        df = pd.DataFrame({
            "node_id": ["node-1"] * 10,
            "timestamp": pd.date_range("2026-08-01", periods=10, freq="1s"),
            "cpu_util": [np.nan] * 10,
            "mem_util": [np.nan] * 10,
            "net_throughput": [np.nan] * 10,
        })
        
        pipeline = FeaturePipeline(
            resample_freq=pipeline_config["resample_freq"],
            max_skew_seconds=pipeline_config["max_skew_seconds"],
            impute_method="ffill",
            interpolation_limit=pipeline_config["interpolation_limit"],
            window_size=pipeline_config["window_size"],
            min_periods=pipeline_config["min_periods"],
        )
        
        result = pipeline.fit_transform(df)
        # Forward fill on all-NaN will produce NaN, but pipeline must not crash
        assert result is not None

    def test_duplicate_timestamps(self, pipeline_config):
        """Duplicate timestamps for same node must be handled."""
        df = valid_raw_telemetry()
        # Duplicate first row
        dup_row = df.iloc[[0]].copy()
        df = pd.concat([df, dup_row], ignore_index=True)
        
        pipeline = FeaturePipeline(
            resample_freq=pipeline_config["resample_freq"],
            max_skew_seconds=pipeline_config["max_skew_seconds"],
            impute_method=pipeline_config["impute_method"],
            interpolation_limit=pipeline_config["interpolation_limit"],
            window_size=pipeline_config["window_size"],
            min_periods=pipeline_config["min_periods"],
        )
        
        # Should either deduplicate or process without error
        result = pipeline.fit_transform(df)
        assert not result.empty

    def test_extreme_values(self, pipeline_config):
        """Values at physical boundaries must be accepted."""
        df = pd.DataFrame({
            "node_id": ["node-1"] * 10,
            "timestamp": pd.date_range("2026-08-01", periods=10, freq="1s"),
            "cpu_util": [0.0, 100.0] * 5,
            "mem_util": [0.0, 100.0] * 5,
            "net_throughput": [0.0, 1e6] * 5,
        })
        
        pipeline = FeaturePipeline(
            resample_freq=pipeline_config["resample_freq"],
            max_skew_seconds=pipeline_config["max_skew_seconds"],
            impute_method=pipeline_config["impute_method"],
            interpolation_limit=pipeline_config["interpolation_limit"],
            window_size=pipeline_config["window_size"],
            min_periods=pipeline_config["min_periods"],
        )
        
        result = pipeline.fit_transform(df)
        assert not result.empty


